<script setup lang="ts">
import { t as uiText } from '@/locales'

import {computed,onMounted,onUnmounted,reactive,ref,watch} from 'vue'
import {useRouter} from 'vue-router'
import {ElMessage} from 'element-plus'
import {getCurrentCatalog,getCurrentCatalogOptions,getCurrentSku,getLocalSnapshots,previewLocalSnapshot,commitLocalSnapshot,type CurrentSku,type CatalogSeries,type CatalogOptions,type CurrentSkuDetail,type ImportPreview} from '@/api/modules/masterData'
import ProductProductionControl from '@/components/ProductionMetadata/ProductProductionControl.vue'
import ScopedRecipePanel from '@/views/bom/components/ScopedRecipePanel.vue'
import {productionStatusName} from '@/utils/productionStatus'
import {useUserStore} from '@/stores/user'
const props=defineProps<{mode?:'product'|'sku'|'bom';administrator?:boolean}>()
const emit=defineEmits<{history:[];maintenance:[id:number]}>(),router=useRouter()
const user=useUserStore()
const query=reactive({page:1,size:50,keyword:'',seriesCode:'',brandId:'',listingStatus:'',productionStatus:''})
const rows=ref<CurrentSku[]>([]),options=ref<CatalogOptions>({series:[],brands:[],total:0,listed:0,purchased:0}),total=ref(0),loading=ref(false),error=ref('')
const selected=ref<CurrentSku>(),detail=ref<CurrentSkuDetail>(),drawer=ref(false),detailLoading=ref(false),detailError=ref('')
const showProducts=computed(()=>props.mode==='product'&&!query.seriesCode)
const selectedSeries=computed(()=>options.value.series.find(s=>s.code===query.seriesCode))
let generation=0,detailGeneration=0,timer:ReturnType<typeof setTimeout>|undefined
async function load(){const epoch=++generation;loading.value=true;error.value='';try{const result=await getCurrentCatalog({...query});if(epoch===generation){rows.value=result.content;total.value=result.totalElements}}catch(e){if(epoch===generation){error.value=e instanceof Error?e.message:'资料读取失败';rows.value=[]}}finally{if(epoch===generation)loading.value=false}}
async function initialize(){try{options.value=await getCurrentCatalogOptions()}catch(e){error.value=e instanceof Error?e.message:'来源选项读取失败'}await load()}
function filter(){query.page=1;void load()}
watch(()=>query.keyword,()=>{clearTimeout(timer);query.page=1;timer=setTimeout(()=>void load(),280)})
watch(()=>props.mode,()=>{query.seriesCode='';filter()})
function openSeries(series:CatalogSeries){query.seriesCode=series.code;filter()}
async function open(row:CurrentSku){selected.value=row;drawer.value=true;detail.value=undefined;detailError.value='';detailLoading.value=true;const epoch=++detailGeneration;try{const value=await getCurrentSku(row.sourceId);if(epoch===detailGeneration)detail.value=value}catch(e){if(epoch===detailGeneration)detailError.value=e instanceof Error?e.message:'详情读取失败'}finally{if(epoch===detailGeneration)detailLoading.value=false}}
function original(){const row=selected.value;if(!row)return;if(row.objectType==='partner')void router.push({path:'/partner-products',query:{id:row.objectId}});else void router.push({path:'/projects',query:{tab:'archived',archiveView:'product',productId:row.objectId,history:'1'}})}
const adminVisible=ref(false),snapshots=ref<Array<{name:string;hash:string;capturedAt:string}>>([]),snapshot=ref(''),preview=ref<ImportPreview>(),reason=ref(''),importBusy=ref(false)
async function admin(){adminVisible.value=true;try{snapshots.value=await getLocalSnapshots();snapshot.value=snapshots.value[0]?.name||''}catch(e){ElMessage.error(e instanceof Error?e.message:uiText('受限来源目录未配置'))}}
async function inspect(){importBusy.value=true;try{preview.value=await previewLocalSnapshot(snapshot.value)}catch(e){ElMessage.error(e instanceof Error?e.message:uiText('预览失败'))}finally{importBusy.value=false}}
async function commit(){if(!preview.value||!reason.value.trim())return;importBusy.value=true;try{await commitLocalSnapshot(preview.value,reason.value.trim());adminVisible.value=false;preview.value=undefined;ElMessage.success(uiText('本地对齐完成；未写入 CRM／MES'));await initialize()}catch(e){ElMessage.error(e instanceof Error?e.message:uiText('导入失败，请重新预览'))}finally{importBusy.value=false}}
watch(()=>user.token,()=>{generation++;detailGeneration++;rows.value=[];options.value={series:[],brands:[],total:0,listed:0,purchased:0};detail.value=undefined;drawer.value=false;adminVisible.value=false;preview.value=undefined;clearTimeout(timer);if(user.token)void initialize()})
onMounted(initialize);onUnmounted(()=>{generation++;detailGeneration++;clearTimeout(timer)})
</script>
<template>
  <section class="current-catalog" :aria-label='uiText("CRM／MES 本期资料")'>
    <header class="catalog-head"><div><strong>{{mode==='bom'?uiText('BOM 与工序用料'):mode==='product'?uiText('本期产品资料'):uiText('本期 SKU')}}</strong><span>{{ uiText("共 ") }}{{options.total}}{{ uiText(" · 已上架 ") }}{{options.listed}}{{ uiText(" · 暂未上架 ") }}{{options.total-options.listed}}</span></div><div class="actions"><el-button v-if="administrator" size="small" @click="admin">{{ uiText("本地来源对齐") }}</el-button><el-button size="small" @click="emit('history')">{{ uiText("历史资料") }}</el-button><el-button size="small" @click="initialize">{{ uiText("刷新") }}</el-button></div></header>
    <div class="catalog-filters"><el-button v-if="selectedSeries" size="small" @click="query.seriesCode='';filter()">{{ uiText("全部产品") }}</el-button><el-input v-model="query.keyword" clearable :placeholder='uiText("品目编码／型号／商品名称")' :aria-label='uiText("搜索当前 SKU")'/><el-select v-model="query.seriesCode" clearable :placeholder='uiText("产品系列")' :aria-label='uiText("产品系列")' @change="filter"><el-option v-for="s in options.series" :key="s.code" :label="`${s.name} · ${s.code}`" :value="s.code"/></el-select><el-select v-model="query.brandId" clearable filterable :placeholder='uiText("品牌")' :aria-label='uiText("品牌")' @change="filter"><el-option v-for="b in options.brands" :key="b.id" :label="b.name" :value="b.id"/></el-select><el-select v-model="query.listingStatus" clearable :placeholder='uiText("上架状态")' :aria-label='uiText("上架状态")' @change="filter"><el-option value="listed" :label='uiText("已上架")'/><el-option value="unlisted" :label='uiText("暂未上架")'/></el-select><el-select v-model="query.productionStatus" clearable :placeholder='uiText("生产状态")' :aria-label='uiText("生产状态")' @change="filter"><el-option value="unknown" :label='uiText("待确认")'/><el-option value="active" :label='uiText("在用")'/><el-option value="discontinued" :label='uiText("已停产")'/></el-select></div>
    <el-alert v-if="error" type="error" :closable="false" :title="error"><el-button link @click="initialize">{{ uiText("重试") }}</el-button></el-alert>
    <div class="catalog-scroll" v-loading="loading">
      <template v-if="showProducts"><article v-for="series in options.series" :key="series.code" class="series-row"><div><strong>{{series.mes?.product_name_cn||series.name}}</strong><code>{{series.code}}</code><el-tag v-if="series.masterDataStatus==='inactive'" size="small" type="info">{{ uiText("基础资料已停用") }}</el-tag><small>{{series.mes?.product_name_en}} {{series.mes?.product_name_es}}</small></div><div><el-tag size="small" :type="series.objectType==='partner'?'info':'primary'">{{series.objectType==='partner'?uiText('合作采购成品'):uiText('自制产品')}}</el-tag><small>{{series.mes?.description_zh||uiText('来源未提供产品描述')}}</small></div><div><ProductProductionControl v-if="series.objectType==='product'" :product-id="series.objectId" :label="series.name"/><small>{{series.skuCount}}{{ uiText(" 条 CRM SKU") }}</small><el-button size="small" @click="openSeries(series)">{{ uiText("查看 SKU 与工程资料") }}</el-button><el-button v-if="series.objectType==='product'" size="small" @click="emit('maintenance',series.objectId)">{{ uiText("资料维护／引用") }}</el-button></div></article></template>
      <template v-else><div class="sku-head"><span>{{ uiText("品目／产品／版本") }}</span><span>{{ uiText("手机型号／品牌／四位码") }}</span><span>{{ uiText("颜色／业务状态") }}</span><span>{{ uiText("操作") }}</span></div><article v-for="row in rows" :key="row.sourceId" class="sku-row"><div><strong>{{row.itemCode}}</strong><el-tag v-if="row.masterDataStatus==='inactive'" size="small" type="info">{{ uiText("基础资料已停用") }}</el-tag><small>{{row.seriesName}} · {{row.seriesCode}}<span v-if="row.commercialVersion"> · {{row.commercialVersion}}</span></small><small v-if="row.sameItemCount>1" class="warning">{{ uiText("同品目 ") }}{{row.sameItemCount}}{{ uiText(" 条来源身份，分别保留") }}</small></div><div><span>{{row.modelName}}</span><small>{{row.brandName}} · {{row.modelCode}}</small><small>{{ uiText("手机生产：") }}{{productionStatusName(row.phoneProductionStatus)}}</small></div><div><span>{{row.colorShortCode}} · {{row.colorNameZh}}</span><small>{{row.colorNameEn}} · {{row.colorNameEs}}</small><div class="tags"><el-tag size="small" :type="row.listingStatus==='listed'?'success':'info'">{{row.listingStatus==='listed'?uiText('已上架'):uiText('暂未上架')}}</el-tag><el-tag size="small" type="info">{{row.purchased?uiText('采购成品'):uiText('产品生产：{value0}',{value0:(productionStatusName(row.productionStatus))})}}</el-tag></div></div><div class="row-actions"><el-button size="small" link type="primary" @click="open(row)">{{mode==='bom'?uiText('用料与路线'):uiText('详情／BOM')}}</el-button><el-button v-if="row.objectType==='product'" size="small" link @click="emit('maintenance',row.objectId)">{{ uiText("资料维护／引用") }}</el-button></div></article><el-empty v-if="!rows.length&&!loading" :description='uiText("没有匹配的本期记录")'/></template>
    </div>
    <footer v-if="!showProducts" class="catalog-pagination"><span>{{selectedSeries?.name||uiText('全部产品')}} · {{total}}{{ uiText(" 条") }}</span><el-pagination :current-page="query.page" :page-size="query.size" :total="total" layout="prev, pager, next" :pager-count="5" @current-change="query.page=$event;load()"/></footer>
    <el-drawer v-model="drawer" :title="selected?.itemCode||uiText('SKU 详情')" size="min(940px,96vw)" destroy-on-close @closed="detailGeneration++">
      <div v-loading="detailLoading"><el-alert v-if="detailError" type="error" :title="detailError" :closable="false"><el-button link @click="selected&&open(selected)">{{ uiText("重试") }}</el-button></el-alert><template v-if="detail&&selected"><div class="detail-heading"><strong>{{selected.productName}}</strong><p>{{selected.brandName}} · {{selected.modelName}} · {{selected.modelCode}}</p><ProductProductionControl v-if="!selected.purchased" :product-id="selected.objectId" :model-value="selected.productionStatus" @changed="load"/><p>{{ uiText("来源状态 ") }}{{selected.sourceStatus}}；{{selected.listingStatus==='listed'?uiText('商城已上架'):uiText('商城暂未上架')}}{{ uiText("；二者不等于人工生产状态。") }}</p><p v-if="detail.source.basePrice!=null">{{ uiText("CRM 原 basePrice：") }}{{detail.source.basePrice}}{{ uiText(" · 来源未提供币种，不作为物料采购成本。") }}</p><el-button size="small" @click="original">{{selected.purchased?uiText('打开合作产品'):uiText('打开原 PLM 档案／项目关系')}}</el-button><el-button v-if="selected.objectType==='product'" size="small" @click="emit('maintenance',selected.objectId)">{{ uiText("资料维护／引用") }}</el-button></div><ScopedRecipePanel :recipes="detail.manufacturing" :purchased="selected.purchased" @changed="open(selected)"/><el-collapse><el-collapse-item :title='uiText("来源字段与对账身份（只读）")'><dl class="source-fields"><div v-for="(value,key) in detail.source" :key="key"><dt>{{key}}</dt><dd>{{value??uiText('未提供')}}</dd></div></dl></el-collapse-item></el-collapse><p class="subtle">{{ uiText("来源快照 ") }}{{selected.observedAt}} · CRM ID {{selected.sourceId}}</p></template></div>
    </el-drawer>
    <el-dialog v-model="adminVisible" :title='uiText("本地 CRM／MES 来源对齐")' width="min(680px,96vw)"><p>{{ uiText("只处理已校验的私有快照，不连接或写入服务器。原状态、历史和对象 ID 保留。") }}</p><el-select v-model="snapshot" :placeholder='uiText("选择不可变来源快照")' style="width:100%" @change="preview=undefined"><el-option v-for="s in snapshots" :key="s.name" :value="s.name" :label="`${s.name} · ${s.capturedAt}`"/></el-select><el-button :disabled="!snapshot" :loading="importBusy" @click="inspect">{{ uiText("重新生成差异预览") }}</el-button><div v-if="preview"><p>{{preview.skuCount}}{{ uiText(" SKU；已上架 ") }}{{preview.listedCount}}{{ uiText("，暂未上架 ") }}{{preview.unlistedCount}}{{ uiText("，采购成品 ") }}{{preview.purchasedCount}}。</p><p>{{preview.warnings.length}}{{ uiText(" 组重复品目身份；") }}{{preview.gaps.length}}{{ uiText(" 条制造资料缺项，均保留原值，不自动猜测。") }}</p><el-input v-model="reason" type="textarea" :maxlength="1000" :placeholder='uiText("填写本地导入原因")'/></div><template #footer><el-button @click="adminVisible=false">{{ uiText("关闭") }}</el-button><el-button type="primary" :disabled="!preview||!reason.trim()" :loading="importBusy" @click="commit">{{ uiText("确认仅写入本地 PLM") }}</el-button></template></el-dialog>
  </section>
</template>
<style scoped>
.current-catalog{height:100%;min-height:0;display:flex;flex-direction:column;gap:8px;container-type:inline-size}.catalog-head,.catalog-head>div,.actions,.catalog-pagination{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.catalog-head{justify-content:space-between}.catalog-head span,.subtle{font-size:12px;color:var(--el-text-color-secondary)}.catalog-filters{display:flex;gap:6px;flex-wrap:wrap}.catalog-filters .el-input{flex:1 1 210px;min-width:120px}.catalog-filters .el-select{flex:1 1 130px;min-width:100px;max-width:220px}.catalog-scroll{flex:1;min-height:0;overflow:auto}.sku-head,.sku-row{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,1.35fr) minmax(0,1fr) 90px;gap:10px;padding:9px 8px}.sku-head{font-size:12px;color:var(--el-text-color-secondary);position:sticky;top:0;background:var(--el-bg-color);z-index:1}.sku-row,.series-row{border-bottom:1px solid var(--el-border-color-lighter);font-size:13px}.sku-row>div,.series-row>div{min-width:0;overflow-wrap:anywhere}.sku-row small,.series-row small{display:block;line-height:1.5;font-size:12px;color:var(--el-text-color-secondary);margin-top:3px}.sku-row .warning{color:var(--el-color-warning-dark-2)}.tags{display:flex;gap:4px;flex-wrap:wrap;margin-top:4px}.series-row{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.6fr) minmax(0,1fr);gap:12px;padding:12px 8px}.series-row code{display:block}.catalog-pagination{justify-content:space-between}.detail-heading{padding-bottom:14px}.source-fields{display:grid;gap:8px}.source-fields>div{display:grid;grid-template-columns:minmax(110px,.4fr) minmax(0,1fr);gap:8px}.source-fields dt{color:var(--el-text-color-secondary)}.source-fields dd{margin:0;white-space:pre-wrap;overflow-wrap:anywhere}.row-actions{display:flex;align-items:center;gap:4px;flex-wrap:wrap}.detail-heading p{overflow-wrap:anywhere}@container(max-width:720px){.sku-head{display:none}.sku-row{grid-template-columns:minmax(0,1fr) minmax(0,1.15fr)}.sku-row>div:last-child{justify-content:flex-end}.series-row{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}.series-row>div:nth-child(2){grid-column:1/-1;grid-row:2}.catalog-head span{width:100%}}@container(max-width:440px){.sku-row{grid-template-columns:1fr}.sku-row>div:last-child{justify-content:flex-start}.catalog-head .actions{gap:4px}.series-row{grid-template-columns:1fr}.catalog-pagination{justify-content:center}}
@container (min-width:581px) and (max-width:720px){.sku-head{display:grid}.sku-row{grid-template-columns:minmax(0,1.15fr) minmax(0,1.35fr) minmax(0,1fr) 78px;gap:8px;padding:8px 6px}.sku-head{grid-template-columns:minmax(0,1.15fr) minmax(0,1.35fr) minmax(0,1fr) 78px;gap:8px}.catalog-filters .el-input{flex:1.5 1 160px}.catalog-filters .el-select{flex:1 1 100px;max-width:none}.catalog-head span{width:auto}}
</style>
